    /**
     * Tests creating a new Warranty.
     *
     * @return    Warranty
     */
    public Warranty testCreate() throws Throwable {
    Warranty entity = null;

    LOGGER.info( "WarrantyTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Warranty");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Warranty" );

    try {
        entity = service.createWarranty( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getWarrantyId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Warranty with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

