    /**
     * Tests getting all Warrantys.
     *
     * @return    Collection
     */
    public List<Warranty> testGetAll() throws Throwable {
    LOGGER.info( "WarrantyTest:testGetAll() - Retrieving Collection of Warrantys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Warranty : " );
    List<Warranty> collection  = null;

    try {
        // call the static get method on the WarrantyService
        collection = service.getAllWarranty();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Warranty currEntity  = null;
            Iterator<Warranty> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getWarrantyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

